/** 
 * Possibly skips the version and flags fields (1+3 byte) of a full meta atom. <p>Atoms of type  {@link Atom#TYPE_meta} are defined to be full atoms which have four additionalbytes for a version and a flags field (see 4.2 'Object Structure' in ISO/IEC 14496-12:2005). QuickTime do not have such a full box structure. Since some of these files are encoded wrongly, we can't rely on the file type though. Instead we must check the 8 bytes after the common header bytes ourselves.
 * @param meta The 8 or more bytes following the meta atom size and type.
 */
public static void maybeSkipRemainingMetaAtomHeaderBytes(ParsableByteArray meta){
  int endPosition=meta.getPosition();
  meta.skipBytes(4);
  if (meta.readInt() != Atom.TYPE_hdlr) {
    endPosition+=4;
  }
  meta.setPosition(endPosition);
}
